  "keywords": [
   {
    "term": "gas exchange",
    "def": "The movement of oxygen into the blood and of carbon dioxide out of the blood, by diffusion, across a gas exchange surface. In humans this surface is the alveoli."
   },
   {
    "term": "diffusion",
    "def": "Diffusion is the net movement of particles from a region of their higher concentration to a region of their lower concentration (i.e. down a concentration gradient), as a result of their random movement. If nothing maintains the concentration gradient, the net movement continues until equilibrium is reached. In the body, equilibrium is usually not reached, because breathing and blood flow maintain the concentration gradient."
   },
   {
    "term": "concentration gradient",
    "def": "A difference in concentration between two regions. Diffusion is the net movement of particles down a concentration gradient — from where they are more concentrated to where they are less concentrated."
   }
  ],
